le" accept=".pdf,.doc,.docx" @change="e=>adjuntosCompra.pedido=e.target.files[0]"></label></div><div class="actions decision-actions"><button class="primary" :disabled="procesando || !decisionCompra" @click="confirmar(decisionCompra==='no'?'noViable':'compra')">{{ decisionCompra==='no' ? 'Continuar: compra no viable' : compraValidada ? 'Elevar a Compras' : 'Confirmar viabilidad' }}</button></div></section>
        <section v-if="ticket.estado_codigo==='EN_VERIFICACION'||ticket.estado_codigo==='PENDIENTE_CONFORMIDAD'" class="action"><small>VERIFICACIÓN DEL SOLICITANTE</small><h3>Pendiente de conformidad</h3><p>El especialista concluyó la atención. La confirmación de funcionamiento corresponde al usuario solicitante.</p></section>
