        <section v-if="ticket.conformidad_usuario===true && (ticket.informe_tecnico||['PENDIENTE_INFORME_FINAL','CERRADO'].includes(ticket.estado_codigo))" class="action"><small>CIERRE TÉCNICO</small><h3>Informe final</h3><div v-if="ticket.informe_tecnico" class="report-block"><div><b>Informe del especialista</b><p>{{ticket.informe_tecnico}}</p></div><button v-if="ticket.evidencia_pruebas_url" type="button" class="report-document" @click="abrirDocumento(ticket.evidencia_pruebas_url,'Respaldo y cuadros técnicos')"><span>PDF</span><b>Ver respaldo y cuadros</b><small>Abrir documento técnico</small></button></div><div v-if="ticket.conformidad_usuario===true" class="description conformity-record"><b>Conformidad del solicitante</b><p><strong>Estado:</strong> Conforme<br><strong>Fecha:</strong> {{fecha(ticket.conformidad_en)}}<br><strong>Usuario:</strong> {{ticket.solicitante_nombre}}</p></div><div v-if="ticket.informe_final" class="report-block final-report"><div><b>Informe final validado</b><p>{{ticket.informe_final}}</p></div><button v-if="ticket.informe_final_pdf_url" type="button" class="report-document" @click="abrirDocumento(ticket.informe_final_pdf_url,'Informe técnico final de Soporte UTIC')"><span>PDF</span><b>Ver informe generado</b><small>Formato institucional aprobado</small></button></div><template v-else-if="ticket.estado_codigo==='PENDIENTE_INFORME_FINAL'"><label class="field">Informe final<textarea v-model="informe" rows="4"></textarea></label><div class="actions"><button class="primary" :disabled="!informe.trim()" @click="elevarInforme">Validar y elevar informe</button></div></template></section>
    </ExpedienteSolicitudModal>

    <ValidacionSolicitud v-if="validacionAbierta && ticket" :registro="ticket" :ocupado="procesando" @cerrar="validacionAbierta=false" @validar="confirmacion='validar'; ejecutarValidacion()" @rechazar="motivo=$event; confirmacion='rechazar'; ejecutarValidacion()" />
    <div v-if="confirmacion" class="backdrop confirm-bg" @click.self="confirmacion=null"><section class="confirm"><i>!</i><h3>{{confirmTitle}}</h3><p>{{confirmText}}</p><label v-if="['rechazar','noViable'].includes(confirmacion)" class="field">{{confirmacion==='noViable'?'Motivo de no viabilidad':'Motivo de no validación'}}<textarea v-model="motivo" rows="4" :placeholder="confirmacion==='noViable'?'Explique por qué la compra no puede continuar…':'Explique al solicitante por qué el ticket no será validado…'"></textarea><small class="field-help">Este mensaje quedará registrado en el expediente y será visible para el usuario correspondiente.</small></label><div v-if="confirmacion==='asignar'" class="selected-user"><b>Especialista</b><span>{{especialistaElegido?.nombre_completo||especialistaElegido?.email}}</span></div><div class="actions"><button @click="confirmacion=null">Cancelar</button><button :class="['primary',{'reject-confirm':['rechazar','noViable'].includes(confirmacion)}]" :disabled="procesando||(['rechazar','noViable'].includes(confirmacion)&&!motivo.trim())" @click="ejecutar">{{['rechazar','noViable'].includes(confirmacion)?'Confirmar y notificar':'Confirmar'}}</button></div></section></div>
    <div v-if="mensaje" class="backdrop confirm-bg" @click.self="mensaje=null"><section class="confirm" :class="mensaje.tipo"><i>{{mensaje.tipo==='error'?'!':'✓'}}</i><h3>{{mensaje.titulo}}</h3><p>{{mensaje.texto}}</p><div class="actions"><button class="primary" @click="mensaje=null">Entendido</button></div></section></div>
    <div v-if="visorEvidencia" class="backdrop evidence-viewer" @click.self="cerrarDocumento"><section><header><button type="button" @click="cerrarDocumento">← Volver al expediente</button><div><small>{{visorTitulo}}</small><h3>{{ticket?.codigo}}</h3></div><button type="button" aria-label="Cerrar" @click="cerrarDocumento">×</button></header><div class="viewer-body"><img v-if="visorEsImagen" :src="visorEvidencia" alt="Documento ampliado"><iframe v-else :src="visorEvidencia" :title="visorTitulo"></iframe></div></section></div>
  </div>
</template>

<script setup>
import { solicitarFirma } from '../utils/firma'
import PrioridadSla from '../components/PrioridadSla.vue'
import DecisionViabilidad from '../components/DecisionViabilidad.vue'
import ExpedienteSolicitudModal from '../components/ExpedienteSolicitudModal.vue'
import ValidacionSolicitud from '../components/ValidacionSolicitud.vue'
import UsuarioHeader from '../components/UsuarioHeader.vue'
import {computed,onMounted,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import LogoutModal from '../components/LogoutModal.vue'
import IconoSigta from '../components/IconoSigta.vue'
const router=useRouter(), usuario=ref(JSON.parse(localStorage.getItem('sigta_usuario')||'{}')), vista=ref('dashboard'), menuAbierto=ref(false), tickets=ref([]), especialistas=ref([]), cargando=ref(false), procesando=ref(false), busqueda=ref(''), ticket=ref(null), confirmacion=ref(null), motivo=ref(''), checklist=ref([]), tecnicoId=ref(''), informe=ref(''), mensaje=ref(null), visorEvidencia=ref(null), visorTitulo=ref('EVIDENCIA DEL TICKET')
const filtros=reactive({texto:'',estado:'',prioridad:'',especialista:'',desde:'',hasta:''}), clasificacion=reactive({prioridad:'',criterio:''})
const checklistItems=['Datos del solicitante verificados','Ubicación y equipo identificados','Descripción suficiente para iniciar atención','Evidencia revisada cuando existe'], pasos=['Validación','Prioridad / SLA','Asignación','Diagnóstico','Compra','Reparación','Pruebas','Conformidad','Informe final'], prioridades=[{codigo:'BAJA',nombre:'Baja',horas:48},{codigo:'MEDIA',nombre:'Media',horas:24},{codigo:'ALTA',nombre:'Alta',horas:8},{codigo:'CRITICA',nombre:'Crítica',horas:4}], definicionColumnas=[{id:'validar',nombre:'Por validar',sigla:'PV',ayuda:'tickets nuevos'},{id:'gestionar',nombre:'Por gestionar',sigla:'PG',ayuda:'clasificación y asignación'},{id:'atencion',nombre:'En atención',sigla:'EA',ayuda:'seguimiento técnico'},{id:'cerrar',nombre:'Por cerrar',sigla:'PC',ayuda:'verificación e informe'}]
const nombre=computed(()=>usuario.value.nombre||usuario.value.nombre_completo||'Jefe de UTIC'),primerNombre=computed(()=>nombre.value.split(' ')[0]),iniciales=computed(()=>nombre.value.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()),saludo=computed(()=>new Date().getHours()<12?'Buenos días':new Date().getHours()<19?'Buenas tardes':'Buenas noches')
const menu=computed(()=>[{id:'dashboard',icono:'panel',nombre:'Dashboard'},{id:'tickets',icono:'tickets',nombre:'Tickets de soporte',total:activos.value.length},{id:'informes',icono:'reporte',nombre:'Informes de los técnicos',total:informesTecnicos.value.length},{id:'historial',icono:'historial',nombre:'Historial'}]),titulo=computed(()=>({dashboard:'Dashboard del Jefe de UTIC',tickets:'Tickets de soporte',informes:'Informes de los técnicos',historial:'Historial de tickets'}[vista.value])),subtitulo=computed(()=>({dashboard:'Gestión y seguimiento centralizado de soporte técnico.',tickets:'Gestione el flujo completo desde una sola bandeja.',informes:'Revise el informe técnico y elabore su informe para elevar a la Dirección.',historial:'Consulta consolidada del ciclo de vida de los tickets.'}[vista.value]))
function columnaTicket(t){if(t.estado_codigo==='NUEVO')return'validar';if(t.estado_codigo==='EN_ANALISIS'||(t.estado_compra_componente==='SOLICITADA'||t.compra_vinculada?.documentos_pendientes?.length))return'gestionar';if(['EN_VERIFICACION','PENDIENTE_CONFORMIDAD','PENDIENTE_INFORME_FINAL','CERRADO'].includes(t.estado_codigo))return'cerrar';return'atencion'}
const informesTecnicos=computed(()=>tickets.value.filter(t=>t.conformidad_usuario===true && (!!t.informe_tecnico||['PENDIENTE_INFORME_FINAL','CERRADO'].includes(t.estado_codigo))))
const activos=computed(()=>tickets.value.filter(t=>!['RECHAZADO','CERRADO_SIN_COMPRA','FINALIZADO','ARCHIVADO'].includes(t.estado_codigo)&&!(t.estado_codigo==='CERRADO'&&t.informe_final))),ticketsKanban=computed(()=>{const q=busqueda.value.trim().toLowerCase();return q?activos.value.filter(t=>`${t.codigo} ${t.titulo} ${t.solicitante_nombre}`.toLowerCase().includes(q)):activos.value}),columnas=computed(()=>({validar:ticketsKanban.value.filter(t=>columnaTicket(t)==='validar'),gestionar:ticketsKanban.value.filter(t=>columnaTicket(t)==='gestionar'),atencion:ticketsKanban.value.filter(t=>columnaTicket(t)==='atencion'),cerrar:ticketsKanban.value.filter(t=>columnaTicket(t)==='cerrar')})),pendientesDashboard=computed(()=>[...columnas.value.validar,...columnas.value.gestionar,...columnas.value.cerrar].slice(0,7))
const necesitaClasificar=computed(()=>ticket.value?.estado_codigo==='EN_ANALISIS'&&!ticket.value?.prioridad),necesitaAsignar=computed(()=>ticket.value?.estado_codigo==='EN_ANALISIS'&&!!ticket.value?.prioridad&&!ticket.value?.tecnico_asignado),estados=computed(()=>[...new Set(tickets.value.map(t=>t.estado_nombre).filter(Boolean))].sort()),especialistaElegido=computed(()=>especialistas.value.find(e=>String(e.id)===String(tecnicoId.value)))
const historial=computed(()=>tickets.value.filter(t=>{const q=filtros.texto.trim().toLowerCase(),f=(t.creado_en||'').slice(0,10);return(!q||`${t.codigo} ${t.titulo}`.toLowerCase().includes(q))&&(!filtros.estado||t.estado_nombre===filtros.estado)&&(!filtros.prioridad||t.prioridad===filtros.prioridad)&&(!filtros.especialista||(filtros.especialista==='sin'?!t.tecnico_asignado:String(t.tecnico_asignado)===filtros.especialista))&&(!filtros.desde||f>=filtros.desde)&&(!filtros.hasta||f<=filtros.hasta)})),confirmTitle=computed(()=>({validar:'Validar ticket',rechazar:'No validar ticket',asignar:'Confirmar asignación',noViable:'Declarar compra no viable',compra:compraValidada.value?'Elevar solicitud de compra':'Validar viabilidad de la compra'}[confirmacion.value])),confirmText=computed(()=>({validar:'¿Confirma que la información es válida y que el ticket puede continuar a clasificación?',rechazar:'El ticket se marcará como no validado, se cerrará y el motivo será comunicado al solicitante.',asignar:'El especialista seleccionado quedará como responsable.',noViable:'El motivo será comunicado al técnico. El ticket se cerrará sin compra y finalizará su proceso.',compra:compraValidada.value?'Se incorporarán el informe técnico y la cotización existentes, junto con el POA y el proveído.':'Se registrará la viabilidad y después podrá adjuntar el POA y el proveído.'}[confirmacion.value]))
const validacionAbierta=ref(false)
async function ejecutarValidacion(){await ejecutar();if(!confirmacion.value)validacionAbierta.value=false}
async function cargar(){cargando.value=true;try{const h={Authorization:`Token ${localStorage.getItem('sigta_token')}`},[r,re]=await Promise.all([fetch('/api/soporte/tickets/',{headers:h}),fetch('/api/usuarios/usuarios-por-rol/?rol=ESPECIALISTA',{headers:h})]),d=await r.json();tickets.value=Array.isArray(d)?d:d.results||[];especialistas.value=re.ok?await re.json():[];if(ticket.value)ticket.value=tickets.value.find(t=>t.id===ticket.value.id)||null}finally{cargando.value=false}}
const mostrarLogout=ref(false)
function salir(){localStorage.removeItem('sigta_token');localStorage.removeItem('sigta_usuario');router.push('/login')}
function confirmarSalida(){mostrarLogout.value=false;salir()}
function verTicket(t){decisionCompra.value=t.estado_compra_componente==='VIABLE'||t.compra_vinculada?'si':'';Object.keys(adjuntosCompra).forEach(k=>adjuntosCompra[k]=null);ticket.value=t;checklist.value=[];clasificacion.prioridad=t.prioridad||'';clasificacion.criterio=t.criterio_tecnico||'';tecnicoId.value=t.tecnico_asignado||'';informe.value=t.informe_final||''} function cerrar(){ticket.value=null;confirmacion.value=null} function confirmar(x){confirmacion.value=x;motivo.value=''}
const decisionCompra=ref('')
const compraValidada=computed(()=>ticket.value?.estado_compra_componente==='VIABLE' || !!ticket.value?.compra_vinculada)
const adjuntosCompra=reactive({poa:null,pedido:null})
function expedienteCompra(){const fd=new FormData();fd.append('viable','true');for(const [campo,archivo] of Object.entries(adjuntosCompra))if(archivo)fd.append(campo,archivo);return fd}
async function post(endpoint,body){procesando.value=true;try{const r=await fetch(`/api/soporte/tickets/${ticket.value.id}/${endpoint}/`,{method:'POST',headers:{Authorization:`Token ${localStorage.getItem('sigta_token')}`,...(body instanceof FormData?{}:{'Content-Type':'application/json'})},body:body instanceof FormData?body:JSON.stringify(body)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detalle||Object.values(d)[0]||'No fue posible completar la acción.');await cargar();return d}finally{procesando.value=false}}
function notificar(titulo,texto,tipo='ok'){mensaje.value={titulo,texto,tipo}}
async function ejecutar(){const accion=confirmacion.value;try{if(accion==='validar')await post('validar-ticket',{es_valido:true});if(accion==='rechazar')await post('validar-ticket',{es_valido:false,motivo_rechazo:motivo.value.trim()});if(accion==='asignar')await post('designar-revision',{tecnico_id:Number(tecnicoId.value),especialistas_apoyo:[]});if(accion==='noViable')await post('evaluar-viabilidad-compra',{viable:false,motivo_no_viable:motivo.value.trim()});if(accion==='compra'){if(!compraValidada.value)await post('validar-viabilidad-compra',{});else{if(!adjuntosCompra.poa||!adjuntosCompra.pedido)throw new Error('Adjunte el POA y el proveído para elevar la compra.');await post(ticket.value.compra_vinculada?.documentos_pendientes?.length?'completar-expediente':'evaluar-viabilidad-compra',expedienteCompra());}}confirmacion.value=null;if(accion==='noViable')notificar('Compra declarada no viable','El técnico fue informado del motivo. El ticket se cerró sin compra y el proceso finalizó.');else if(accion==='rechazar')notificar('Ticket no validado','El motivo quedó registrado y fue comunicado al solicitante. El ticket fue cerrado.');else notificar('Acción completada','El expediente fue actualizado correctamente.')}catch(e){notificar('No se pudo completar la acción',String(e.message),'error')}} async function clasificar(){try{await post('clasificar-prioridad',{prioridad:clasificacion.prioridad,criterio_tecnico:clasificacion.criterio.trim()});notificar('Prioridad guardada','El SLA fue calculado y el expediente avanzó a asignación.')}catch(e){notificar('No se pudo clasificar',String(e.message),'error')}} async function verificar(ok){try{await post('verificar-funcionamiento',{funciona_correctamente:ok});notificar('Verificación registrada','El estado del expediente fue actualizado.')}catch(e){notificar('No se pudo verificar',String(e.message),'error')}} async function elevarInforme(){const firma=await solicitarFirma('Informe final de soporte',ticket.value.codigo);if(!firma)return;try{await post('elaborar-informe-final',{informe_final:informe.value.trim(),firma});notificar('Informe final enviado','El PDF fue generado con los campos del expediente y elevado a la Dirección.')}catch(e){notificar('No se pudo enviar el informe',String(e.message),'error')}}
function cargaEspecialista(id){return activos.value.filter(t=>Number(t.tecnico_asignado)===Number(id)).length}
function prioridadTexto(p){return({BAJA:'Baja',MEDIA:'Media',ALTA:'Alta',CRITICA:'Crítica'}[p]||'Sin clasificar')} function estadoBadgeClase(t){const c=t.estado_codigo;if(['CERRADO','FINALIZADO','ARCHIVADO'].includes(c))return'cerrado';if(['RECHAZADO','CERRADO_SIN_COMPRA'].includes(c))return'rechazado';if(['PENDIENTE_INFORME_FINAL','PENDIENTE_CONFORMIDAD','EN_VERIFICACION'].includes(c))return'pendiente';if(c==='NUEVO')return'nuevo';return'proceso'} function slaTexto(t){return t.sla_horas?`${t.sla_horas} h${t.sla_estado?' · '+t.sla_estado:''}`:'Sin asignar'} function fecha(f){return f?new Intl.DateTimeFormat('es-BO',{dateStyle:'short'}).format(new Date(f)):'—'} function esImagen(u){return /\.(png|jpe?g|gif|webp)(\?|$)/i.test(u||'')} function nombreArchivo(u){return decodeURIComponent((u||'').split('/').pop().split('?')[0])}
const visorEsImagen=ref(false)
async function abrirDocumento(url,titulo='Documento del expediente'){
  try{
    const respuesta=await fetch(url,{headers:{Authorization:`Token ${localStorage.getItem('sigta_token')}`},cache:'no-store'})
    if(!respuesta.ok)throw new Error('No se pudo abrir el documento. Actualice el expediente e intente nuevamente.')
    const archivo=await respuesta.blob()
    cerrarDocumento()
    visorEsImagen.value=archivo.type.startsWith('image/')
    visorEvidencia.value=URL.createObjectURL(archivo)
    visorTitulo.value=titulo.toUpperCase()
  }catch(error){notificar('No se pudo visualizar',error.message,'error')}
}
function cerrarDocumento(){if(visorEvidencia.value?.startsWith('blob:'))URL.revokeObjectURL(visorEvidencia.value);visorEvidencia.value=null;visorTitulo.value='EVIDENCIA DEL TICKET'}

function pasoClase(p){const t=ticket.value,hecho=[t.estado_codigo!=='NUEVO',!!t.prioridad,!!t.tecnico_asignado,!!t.diagnostico,!t.requiere_compra||['VIABLE','NO_VIABLE','ENTREGADA'].includes(t.estado_compra_componente),!!t.solucion,!!t.resultado_pruebas,t.conformidad_usuario!==null,!!t.informe_final];if(hecho[p-1])return'done';const primero=hecho.findIndex(x=>!x)+1;return p===primero?'active':''} function pasoEstado(p){return pasoClase(p)==='done'?'Completado':pasoClase(p)==='active'?'Etapa actual':'Aún no disponible'}
onMounted(cargar)
</script>

